import{_ as p,a0 as o,w as d,s as r,ao as l,I as i,x as n,a1 as e,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"三款简单而优秀的 Linux 网络监视工具 | LCTT x X-CMD","titleTemplate":false,"description":"三款简单而优秀的 Linux 网络监视工具 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"三款简单而优秀的 Linux 网络监视工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"三款简单而优秀的 Linux 网络监视工具 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20171019 3 Simple Excellent Linux Network Monitors","title":"三款简单而优秀的 Linux 网络监视工具","tag":"201801","desc":""},"relativePath":"201801/20171019 3 Simple Excellent Linux Network Monitors.md","filePath":"[post].md"}'),c={name:"201801/20171019 3 Simple Excellent Linux Network Monitors.md"};function u(g,s,h,k,b,f){const a=o("Link");return d(),r("div",null,[s[30]||(s[30]=l(`<h1 id="三款简单而优秀的-linux-网络监视工具" tabindex="-1">三款简单而优秀的 Linux 网络监视工具 <a class="header-anchor" href="#三款简单而优秀的-linux-网络监视工具" aria-label="Permalink to “三款简单而优秀的 Linux 网络监视工具”">​</a></h1><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/banner_3.png?itok=iuPcSN4k" alt="network" title="network"></p><blockquote><p>通过 <code>iftop</code>、 <code>nethogs</code> 和 <code>vnstat</code> 详细了解你的网络连接状态。</p></blockquote><p>你可以通过这三个 Linux 命令了解当前网络的大量信息。<code>iftop</code> 通过进程号跟踪网络连接，<code>nethogs</code> 快速告知你哪些进程在占用你的带宽，而 <code>vnstat</code> 以一个良好的轻量级守护进程在后台运行，并实时记录你的网络使用情况。</p><h3 id="iftop" tabindex="-1">iftop <a class="header-anchor" href="#iftop" aria-label="Permalink to “iftop”">​</a></h3><p>令人称赞的 <code>iftop</code> 可以监听您指定的网络接口，并以 top 的样式呈现。</p><p>这是一个不错的小工具，可以用于找出网络拥塞，测速和维持网络流量总量。看到自己到底在用多少带宽往往是非常惊人的，尤其是对于我们这些仍然记得电话线路、调制解调器，“高速”到令人惊叫的 kb 和实时波特率的老人们。我们在很久之前就不再使用波特率，转而钟情于比特率。波特率用于衡量信号变化，尽管有时候与比特率相同，但大多数情况下并非如此。</p><p>如果你只有一个网络接口，直接运行 <code>iftop</code> 即可。不过 <code>iftop</code> 需要 root 权限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo iftop</span></span></code></pre></div><p>如果你有多个网络接口，那就指定你要监控的接口：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo iftop -i wlan0</span></span></code></pre></div><p>就像 <code>top</code> 命令一样，你可以在命令运行时更改显示选项：</p><ul><li><code>h</code> 切换帮助界面。</li><li><code>n</code> 是否解析域名。</li><li><code>s</code> 切换源地址的显示，<code>d</code> 则切换目的地址的显示。</li><li><code>S</code> 是否显示端口号。</li><li><code>N</code> 是否解析端口；若关闭解析则显示端口号。</li><li><code>t</code> 切换文本显示界面。默认的显示方式需要 ncurses。我个人认为图 1 的显示方式在组织性和可读性都更加良好。</li><li><code>p</code> 暂停显示更新。</li><li><code>q</code> 退出程序。</li></ul><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/fig-1_8.png?itok=luKHS5ve" alt="text display" title="text display"></p><p><em>图 1:组织性和可读性良好的文本显示。</em></p><p>当你切换显示设置的时候，<code>iftop</code> 并不会中断监测流量。当然你也可以单独监测一台主机。而这需要该主机的 IP 地址和子网掩码。现在，我很好奇 Pandora（LCTT 译注：一家美国的电台公司）能给我贫瘠的带宽带来多大的负载。因此我首先使用 dig 命令找到他们的 IP 地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dig A pandora.com</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>;; ANSWER SECTION:</span></span>
<span class="line"><span>pandora.com.            267     IN      A       208.85.40.20</span></span>
<span class="line"><span>pandora.com.            267     IN      A       208.85.40.50</span></span></code></pre></div>`,17)),i("p",null,[s[1]||(s[1]=n("那子网掩码呢？",-1)),e(a,{href:"https://www.linux.com/learn/intro-to-linux/2017/8/how-calculate-network-addresses-ipcalc"},{default:t(()=>[...s[0]||(s[0]=[n("ipcalc",-1)])]),_:1}),s[2]||(s[2]=n(" 会告诉我们：",-1))]),s[31]||(s[31]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ipcalc -b 208.85.40.20</span></span>
<span class="line"><span>Address:   208.85.40.20   </span></span>
<span class="line"><span>Netmask:   255.255.255.0 = 24</span></span>
<span class="line"><span>Wildcard:  0.0.0.255  </span></span>
<span class="line"><span>=&gt;</span></span>
<span class="line"><span>Network:   208.85.40.0/24</span></span></code></pre></div><p>现在，将 IP 地址和子网掩码提供给 <code>iftop</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo iftop -F 208.85.40.20/24 -i wlan0</span></span></code></pre></div><p>很棒的不是么？而我也很惊奇地发现，Pandora 在我的网络上，每小时大约使用 500kb。并且就像大多数流媒体服务一样，Pandora 的流量在迅速增长，并依靠缓存稳定下来。</p>`,4)),i("p",null,[s[4]||(s[4]=n("你可以使用 ",-1)),s[5]||(s[5]=i("code",null,"-G",-1)),s[6]||(s[6]=n(" 选项对 IPv6 地址执行相同的操作。查阅友好的 man 可以帮助你了解 ",-1)),s[7]||(s[7]=i("code",null,"iftop",-1)),s[8]||(s[8]=n(" 的其他功能，包括使用个人配置文件自定义你的默认选项，以及使用自定义过滤（请参阅 ",-1)),e(a,{href:"http://www.tcpdump.org/manpages/pcap-filter.7.html"},{default:t(()=>[...s[3]||(s[3]=[n("PCAP-FILTER",-1)])]),_:1}),s[9]||(s[9]=n(" 来获取过滤指南）。",-1))]),s[32]||(s[32]=l(`<h3 id="nethogs" tabindex="-1">nethogs <a class="header-anchor" href="#nethogs" aria-label="Permalink to “nethogs”">​</a></h3><p>当你想要快速了解是谁在吸取你的带宽的时候，<code>nethogs</code> 是个快速而简单的方法。你需要以 root 身份运行并指定要监听的接口。它会给你显示大量的应用程序及其进程号，所以如果你想的话，你可以借此杀死任一进程。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nethogs wlan0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>nethogs version 0.8.1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PID USER   PROGRAM              DEV    SENT   RECEIVED       </span></span>
<span class="line"><span>7690 carla /usr/lib/firefox     wlan0 12.494 556.580 KB/sec</span></span>
<span class="line"><span>5648 carla .../chromium-browser wlan0  0.052   0.038 KB/sec</span></span>
<span class="line"><span>TOTAL                                 12.546 556.618 KB/sec</span></span></code></pre></div><p><code>nethogs</code> 并没有多少选项：在 kb/s、kb、b、mb之间循环，按接收和发送的数据包排序，调整刷新延迟。具体请看<code>man nethogs</code>，或者是运行 <code>nethogs -h</code>。</p><h3 id="vnstat" tabindex="-1">vnstat <a class="header-anchor" href="#vnstat" aria-label="Permalink to “vnstat”">​</a></h3>`,5)),i("p",null,[e(a,{href:"http://humdi.net/vnstat/"},{default:t(()=>[...s[10]||(s[10]=[n("vnstat",-1)])]),_:1}),s[11]||(s[11]=n("是最容易使用的网络数据收集工具。它十分轻量并且不需要 root 权限。它以守护进程在后台运行，因此可以实时地记录你的网络数据。单个 ",-1)),s[12]||(s[12]=i("code",null,"vnstat",-1)),s[13]||(s[13]=n(" 命令就可以显示所累计的数据。",-1))]),s[33]||(s[33]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vnstat -i wlan0</span></span>
<span class="line"><span>Database updated: Tue Oct 17 08:36:38 2017</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   wlan0 since 10/17/2017</span></span>
<span class="line"><span></span></span>
<span class="line"><span>          rx:  45.27 MiB      tx:  3.77 MiB      total:  49.04 MiB</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   monthly</span></span>
<span class="line"><span>                     rx      |     tx      |    total    |   avg. rate</span></span>
<span class="line"><span>     ------------------------+-------------+-------------+---------------</span></span>
<span class="line"><span>       Oct &#39;17     45.27 MiB |    3.77 MiB |   49.04 MiB |    0.28 kbit/s</span></span>
<span class="line"><span>     ------------------------+-------------+-------------+---------------</span></span>
<span class="line"><span>     estimated        85 MiB |       5 MiB |      90 MiB |</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   daily</span></span>
<span class="line"><span>                     rx      |     tx      |    total    |   avg. rate</span></span>
<span class="line"><span>     ------------------------+-------------+-------------+---------------</span></span>
<span class="line"><span>         today     45.27 MiB |    3.77 MiB |   49.04 MiB |   12.96 kbit/s</span></span>
<span class="line"><span>     ------------------------+-------------+-------------+---------------</span></span>
<span class="line"><span>     estimated       125 MiB |       8 MiB |     133 MiB |</span></span></code></pre></div><p>默认情况下它会显示所有的网络接口。使用 <code>-i</code> 选项来选择某个接口。也可以像这样合并多个接口的数据：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vnstat -i wlan0+eth0+eth1</span></span></code></pre></div><p>你可以通过这几种方式过滤数据显示：</p><ul><li><code>-h</code> 按小时显示统计信息。</li><li><code>-d</code> 按天显示统计信息.</li><li><code>-w</code> 和 <code>-m</code> 分别按周和月份来显示统计信息。</li><li>使用 <code>-l</code> 选项查看实时更新。</li></ul><p>以下这条命令将会删除 wlan1 的数据库并不再监视它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vnstat -i wlan1 --delete</span></span></code></pre></div><p>而下面这条命令将会为你的一个网络接口创建一个别名。这个例子使用了 Ubuntu 16.04 的一个有线接口名称：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vnstat -u -i enp0s25 --nick eth0</span></span></code></pre></div><p>默认情况下，vnstat 会监视 eth0。你可以在 <code>/etc/vnstat.conf</code> 对它进行修改，或者在你的家目录下创建你自己的个人配置文件。请参阅 <code>man vnstat</code> 以获取完整的指南。</p><p>你也可以安装 <code>vnstati</code> 来创建简单的彩图（图 2）:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vnstati -s -i wlx7cdd90a0a1c2 -o vnstat.png</span></span></code></pre></div><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/fig-2_5.png?itok=HsWJMcW0" alt="vnstati" title="vnstati"></p><p><em>图 2:你可以使用vnstati来创建简单的彩图。</em></p><p>请参阅 <code>man vnstati</code> 以获取完整的选项。</p>`,15)),i("p",null,[i("em",null,[s[15]||(s[15]=n("欲了解 Linux 的更多信息，可以通过学习 Linux 基金会和 edX 的免费课程，",-1)),e(a,{href:"https://training.linuxfoundation.org/linux-courses/system-administration-training/introduction-to-linux"},{default:t(()=>[...s[14]||(s[14]=[n("“Linux 入门”",-1)])]),_:1}),s[16]||(s[16]=n("。",-1))])]),s[34]||(s[34]=i("hr",null,null,-1)),i("p",null,[s[18]||(s[18]=n("via: ",-1)),e(a,{href:"https://www.linux.com/learn/intro-to-linux/2017/10/3-simple-excellent-linux-network-monitors"},{default:t(()=>[...s[17]||(s[17]=[n("https://www.linux.com/learn/intro-to-linux/2017/10/3-simple-excellent-linux-network-monitors",-1)])]),_:1})]),i("p",null,[s[22]||(s[22]=n("作者：",-1)),e(a,{href:"https://www.linux.com/users/cschroder"},{default:t(()=>[...s[19]||(s[19]=[n("CARLA SCHRODER",-1)])]),_:1}),s[23]||(s[23]=n(" 译者：",-1)),e(a,{href:"https://github.com/KeyLD"},{default:t(()=>[...s[20]||(s[20]=[n("KeyLD",-1)])]),_:1}),s[24]||(s[24]=n(" 校对：",-1)),e(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[21]||(s[21]=[n("wxy",-1)])]),_:1})]),i("p",null,[s[27]||(s[27]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[25]||(s[25]=[n("LCTT",-1)])]),_:1}),s[28]||(s[28]=n(" 原创编译，",-1)),e(a,{href:"https://linux.cn/"},{default:t(()=>[...s[26]||(s[26]=[n("Linux中国",-1)])]),_:1}),s[29]||(s[29]=n(" 荣誉推出",-1))])])}const w=p(c,[["render",u]]);export{v as __pageData,w as default};
